from __future__ import annotations

MYSQL_CONTRACT_DDL = (
    "\n                CREATE TABLE IF NOT EXISTS contracts (\n                    contract_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    source_type VARCHAR(24) NOT NULL,\n                    source_ref VARCHAR(64) NOT NULL DEFAULT '',\n                    creator_id BIGINT UNSIGNED NULL,\n                    assignee_id BIGINT UNSIGNED NULL,\n                    title VARCHAR(120) NOT NULL,\n                    reward_amount DECIMAL(65,0) NOT NULL,\n                    escrow_state VARCHAR(16) NOT NULL DEFAULT 'held',\n                    escrow_wallet_amount DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    escrow_bank_amount DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    status VARCHAR(16) NOT NULL DEFAULT 'open',\n                    created_at VARCHAR(64) NOT NULL,\n                    expires_at VARCHAR(64) NOT NULL,\n                    accepted_at VARCHAR(64) NULL,\n                    resolved_at VARCHAR(64) NULL,\n                    PRIMARY KEY (contract_id),\n                    KEY idx_contracts_active (guild_id,status,expires_at),\n                    KEY idx_contracts_assignee (guild_id,assignee_id,status,contract_id),\n                    KEY idx_contracts_creator (guild_id,creator_id,status,contract_id)\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ",
    "\n                CREATE TABLE IF NOT EXISTS contract_objectives (\n                    objective_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    contract_id BIGINT UNSIGNED NOT NULL,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    objective_key VARCHAR(64) NOT NULL,\n                    objective_type VARCHAR(32) NOT NULL,\n                    target_ref VARCHAR(128) NOT NULL,\n                    required_value DECIMAL(65,0) NOT NULL,\n                    current_value DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    status VARCHAR(16) NOT NULL DEFAULT 'pending',\n                    verification_mode VARCHAR(24) NOT NULL DEFAULT 'domain_event',\n                    metadata_json LONGTEXT NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    updated_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (objective_id),\n                    UNIQUE KEY uq_contract_objective_key (contract_id,objective_key),\n                    KEY idx_contract_objectives_active (guild_id,contract_id,status,objective_type,target_ref),\n                    CONSTRAINT fk_contract_objective_contract\n                        FOREIGN KEY (contract_id) REFERENCES contracts (contract_id)\n                        ON UPDATE CASCADE ON DELETE CASCADE\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ",
    '\n                CREATE TABLE IF NOT EXISTS contract_events (\n                    event_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    contract_id BIGINT UNSIGNED NOT NULL,\n                    event_key VARCHAR(160) NOT NULL,\n                    event_type VARCHAR(40) NOT NULL,\n                    actor_id BIGINT UNSIGNED NOT NULL,\n                    target_ref VARCHAR(128) NOT NULL,\n                    delta DECIMAL(65,0) NOT NULL DEFAULT 1,\n                    payload_json LONGTEXT NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (event_id),\n                    UNIQUE KEY uq_contract_event_key (guild_id,contract_id,event_key),\n                    KEY idx_contract_events_contract (guild_id,contract_id,event_id),\n                    CONSTRAINT fk_contract_event_contract\n                        FOREIGN KEY (contract_id) REFERENCES contracts (contract_id)\n                        ON UPDATE CASCADE ON DELETE CASCADE\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ',
    '\n                CREATE TABLE IF NOT EXISTS contract_history (\n                    history_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    contract_id BIGINT UNSIGNED NOT NULL,\n                    event_key VARCHAR(190) NOT NULL,\n                    event_type VARCHAR(40) NOT NULL,\n                    actor_id BIGINT UNSIGNED NULL,\n                    metadata_json LONGTEXT NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (history_id),\n                    UNIQUE KEY uq_contract_history_event (guild_id,contract_id,event_key),\n                    KEY idx_contract_history_contract (guild_id,contract_id,history_id),\n                    CONSTRAINT fk_contract_history_contract\n                        FOREIGN KEY (contract_id) REFERENCES contracts (contract_id)\n                        ON UPDATE CASCADE ON DELETE CASCADE\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ',
    '\n                CREATE TABLE IF NOT EXISTS contract_event_claims (\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    event_key VARCHAR(190) NOT NULL,\n                    contract_id BIGINT UNSIGNED NOT NULL,\n                    event_type VARCHAR(40) NOT NULL,\n                    actor_id BIGINT UNSIGNED NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (guild_id,event_key),\n                    KEY idx_contract_event_claim_contract (guild_id,contract_id),\n                    CONSTRAINT fk_contract_event_claim_contract\n                        FOREIGN KEY (contract_id) REFERENCES contracts (contract_id)\n                        ON UPDATE CASCADE ON DELETE CASCADE\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ',
    '\n                CREATE TABLE IF NOT EXISTS item_transfer_history (\n                    transfer_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    sender_id BIGINT UNSIGNED NOT NULL,\n                    receiver_id BIGINT UNSIGNED NOT NULL,\n                    item_id VARCHAR(64) NOT NULL,\n                    quantity DECIMAL(65,0) NOT NULL,\n                    source_ref VARCHAR(190) NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (transfer_id),\n                    UNIQUE KEY uq_item_transfer_source (guild_id,source_ref),\n                    KEY idx_item_transfer_users (guild_id,sender_id,receiver_id,transfer_id)\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ',
    '\n                CREATE TABLE IF NOT EXISTS contract_reward_budgets (\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    budget_key VARCHAR(64) NOT NULL,\n                    period_key VARCHAR(32) NOT NULL,\n                    limit_amount DECIMAL(65,0) NOT NULL,\n                    reserved_amount DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    spent_amount DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    updated_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (guild_id,budget_key,period_key)\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ',
    "\n                CREATE TABLE IF NOT EXISTS contract_source_state (\n                    contract_id BIGINT UNSIGNED NOT NULL,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    source_key VARCHAR(64) NOT NULL,\n                    source_label VARCHAR(120) NOT NULL,\n                    target_user_id BIGINT UNSIGNED NOT NULL DEFAULT 0,\n                    budget_key VARCHAR(64) NOT NULL DEFAULT '',\n                    budget_period VARCHAR(32) NOT NULL DEFAULT '',\n                    eligibility_json LONGTEXT NOT NULL,\n                    modifier_json LONGTEXT NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (contract_id),\n                    UNIQUE KEY uq_contract_source_cycle (guild_id,source_key,budget_period,target_user_id),\n                    KEY idx_contract_source_target (guild_id,target_user_id,source_key),\n                    CONSTRAINT fk_contract_source_contract FOREIGN KEY (contract_id) REFERENCES contracts (contract_id)\n                        ON UPDATE CASCADE ON DELETE CASCADE\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ",
    "\n                CREATE TABLE IF NOT EXISTS contract_telemetry (\n                    telemetry_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    event_key VARCHAR(190) NOT NULL,\n                    event_type VARCHAR(48) NOT NULL,\n                    contract_id BIGINT UNSIGNED NULL,\n                    actor_id BIGINT UNSIGNED NULL,\n                    counterparty_id BIGINT UNSIGNED NULL,\n                    source_key VARCHAR(64) NOT NULL DEFAULT '',\n                    reward_amount DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    details_json LONGTEXT NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (telemetry_id),\n                    UNIQUE KEY uq_contract_telemetry_event (guild_id,event_key),\n                    KEY idx_contract_telemetry_type (guild_id,event_type,created_at),\n                    KEY idx_contract_telemetry_contract (guild_id,contract_id,telemetry_id)\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ",
    '\n                CREATE TABLE IF NOT EXISTS business_delivery_history (\n                    delivery_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    property_id BIGINT UNSIGNED NOT NULL,\n                    provider_user_id BIGINT UNSIGNED NOT NULL,\n                    item_id VARCHAR(64) NOT NULL,\n                    quantity DECIMAL(65,0) NOT NULL,\n                    source_ref VARCHAR(190) NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (delivery_id),\n                    UNIQUE KEY uq_business_delivery_source (guild_id,source_ref),\n                    KEY idx_business_delivery_property (guild_id,property_id,delivery_id)\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ',
)
